namespace Tests\Feature;

use Aic\Hub\Foundation\Testing\FeatureTestCase as BaseTestCase;
use Aic\Hub\Foundation\Testing\MockApi;
use App\Models\Article;
use App\Models\Event;
use Database\Seeders\PercyFixtureSeeder;

/**
 * Percy snapshots address the fixture article and event by pinned id (see
 * tests-percy/fixtures.js), so these must stay routable after seeding.
 */
class PercyFixtureSeederTest extends BaseTestCase
{
    use MockApi;

    protected function setUp(): void
    {
        parent::setUp();
        $this->seed();
        $this->seed(PercyFixtureSeeder::class);
    }

    public function test_fixture_article_renders_at_pinned_id(): void
    {
        $response = $this->followingRedirects()->get('/articles/' . PercyFixtureSeeder::ARTICLE_ID);
        $response->assertOk();
        $response->assertSee('Percy Fixture Article');
        $response->assertSee('o-article--editorial', false);
    }

    public function test_fixture_event_renders_at_pinned_id(): void
    {
        // The event presenter can look up ticketing data through the API.
        $this->addMockApiResponses([
            $this->mockApiSearchResponse(),
            $this->mockApiSearchResponse(),
            $this->mockApiSearchResponse(),
            $this->mockApiSearchResponse(),
        ]);

        $response = $this->followingRedirects()->get('/events/' . PercyFixtureSeeder::EVENT_ID);
        $response->assertOk();
        $response->assertSee('Percy Fixture Event');
    }

    public function test_fixture_event_has_a_single_fixed_past_occurrence(): void
    {
        $event = Event::findOrFail(PercyFixtureSeeder::EVENT_ID);

        $this->assertFalse($event->is_recurring);
        $this->assertCount(1, $event->eventMetas);
        $this->assertSame('2024-01-15 14:00:00', $event->eventMetas->first()->date->format('Y-m-d H:i:s'));
    }

    public function test_seeder_is_idempotent(): void
    {
        $this->seed(PercyFixtureSeeder::class);

        $this->assertSame(1, Article::where('id', PercyFixtureSeeder::ARTICLE_ID)->count());
        $this->assertSame(1, Event::findOrFail(PercyFixtureSeeder::EVENT_ID)->eventMetas()->count());
    }
}
